public async Task<Dictionary<int, int>> GetTotalViewsByBlogAsync(
    BlogContext context,
    string searchTerm,
    CancellationToken cancellationToken)
{
    var totalsQuery =
        from post in context.Posts
        where post.Title.Contains(searchTerm)
        group post.Views by post.BlogId into blogViews
        select new { BlogId = blogViews.Key, TotalViews = blogViews.Sum() };

    var totals = await totalsQuery.ToListAsync(cancellationToken);

    return totals.ToDictionary(total => total.BlogId, total => total.TotalViews);
}
